new_events.ndim == 3\n47:     batch, length, width = state.shape\n48:     assert new_events.shape[0] == batch and new_events.shape[2] == width\n49:     steps = new_events.shape[1]\n50:     assert 1 <= batch <= 4 and 2 <= length <= 4096 and 1 <= width <= 1024\n51:     assert 1 <= steps <= min(length, 128)\n52:     with torch.no_grad():\n53:         source = state.resolve_neg()\n54:         events_source = new_events.resolve_neg()\n55:     output = torch.empty_like(state)\n56:     _slide[(triton.cdiv(state.numel(), 1024),)](\n57:         source, events_source, output, length, width, steps, state.numel(),\n58:         BLOCK=1024, num_warps=4,\n59:     )\n60:     _writeback[(triton.cdiv(state.numel(), 1024),)](\n61:         output, state, state.numel(), NEGATE=state.is_neg(), BLOCK=1024, num_warps=4,\n62:     )\n63:     return state\n64: \n65: \n66: def reference(state, new_events):\n67:     \"\"\"Independent result computed from the pre-call state, without mutation.\"\"\"\n68:     return torch.cat((state[:, new_events.shape[1]:, :], new_events), dim=1)\n69: \n70: \n71: def make_inputs(device=\"cuda\", batch=4, length=2048, width=1024,\n72:                 steps=2, seed=0):\n73:     \"\"\"One convenient example; any legal input may be tested.\"\"\"\n74:     generator = torch.Generator(device=\"cpu\").manual_seed(seed)\n75:     state = torch.randn((batch, length, width), generator=generator)\n76:     new_events = torch.randn((batch, steps, width), generator=generator)\n77:     return state.to(device), new_events.to(device)",
